<script setup lang="ts">
import {computed,onMounted,reactive,ref,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {ElMessage,ElMessageBox} from 'element-plus';
import {request,post,patch,remove,queryString} from '@/utils/request';
import {usePermissions} from '@/store/modules/permission.store';
import {Search,Refresh,ArrowDown} from '@element-plus/icons-vue';
import {downloadWorkbook} from '@/utils/workbook';
import {mallApi} from '@/api/mall/mall.api';
const route=useRoute(),router=useRouter(),permissions=usePermissions();
const recycled=computed(()=>Boolean(route.meta.recycled));
const type=ref(Number(route.query.type)===20?20:1),category=ref(String(route.query.category||'allIp')),query=ref(''),page=ref(1),total=ref(0),items=ref<any[]>([]),stats=ref<Record<string,number>>({}),loading=ref(false);
const selected=ref<any[]>([]),size=ref(20),counts=ref<Record<number,number>>({}),bindings=ref<any>(),boundShops=ref<any[]>([]),shopChoices=ref<any[]>([]),shopId=ref(''),shopSearch=ref('');
const exportColumns={id:'设备 ID（编辑必填，新增留空）',name:'设备名称',protocol:'协议',host:'设备信息',port:'端口',username:'代理账号',region:'设备地域',boundCount:'绑定店铺数',remark:'备注',expiresAt:'到期时间'};
const categories=[['allIp','全部'],['willExpiredIp','即将到期'],['expiredIp','已到期'],['unbindMall','未绑定店铺'],['unAutoRenew','未自动续费'],['autoRenew','自动续费']];
async function load(){loading.value=true;try{const q={type:type.value,category:category.value,query:query.value,page:page.value,size:size.value,recycled:recycled.value};const r=await request('/devices?'+queryString(q));items.value=r.items;total.value=r.total;stats.value=await request('/devices/statistics?'+queryString({type:type.value,recycled:recycled.value}));await Promise.all([1,20].map(async t=>counts.value[t]=(await request(`/devices?type=${t}&recycled=${recycled.value}&size=1`)).total));}finally{loading.value=false;}}
watch([type,category,recycled],()=>{page.value=1;load();});onMounted(load);
const editing=ref(false),saving=ref(false),form=reactive<any>({});
function edit(row:any){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,{id:row.id,name:row.name,remark:row.remark});editing.value=true;}
async function save(){saving.value=true;try{await patch('/devices/'+form.id,{name:form.name,remark:form.remark});editing.value=false;await load();}finally{saving.value=false;}}
async function recycle(row:any){try{await ElMessageBox.confirm(recycled.value?'是否彻底删除设备？设备删除后将无法找回，请谨慎操作。':'将设备移入回收站？若删除的是未过期设备，在设备过期前可在回收站找回。绑定中的设备需先解绑。','确认操作');}catch{return;}await remove(`/devices/${row.id}?permanent=${recycled.value}`);await load();}
async function restore(row:any){await post(`/devices/${row.id}/restore`);await load();}
async function autoRenew(row:any){await patch(`/devices/${row.id}/auto-renew`,{enabled:!row.autoRenew});await load();}
async function check(row:any){if(!window.api)throw new Error('请在桌面客户端中检测代理连接');const result=await window.api.checkProxy(row.id);ElMessage({message:result.message,type:result.connected?'success':'error'});}
async function exportAll(){const all:any[]=[];for(let p=1;;p++){const r=await request('/devices?'+queryString({type:type.value,category:category.value,query:query.value,recycled:recycled.value,page:p,size:200}));all.push(...r.items);if(all.length>=r.total)break;}await downloadWorkbook('设备列表.xlsx',all,exportColumns);}
async function searchShops(){shopChoices.value=(await request(`/environments?query=${encodeURIComponent(shopSearch.value)}&size=100`)).items;}
async function showBindings(row:any){bindings.value=row;boundShops.value=await request(`/devices/${row.id}/environments`);shopId.value='';await searchShops();}
async function bindShop(){await mallApi.bind(shopId.value,bindings.value.id);await showBindings(bindings.value);await load();}
async function unbindShop(row:any){await mallApi.bind(row.id,'');await showBindings(bindings.value);await load();}
async function batch(action:string){try{await ElMessageBox.confirm(`对所选 ${selected.value.length} 台设备执行${action==='restore'?'恢复':action==='renewOn'?'开启自动续费':action==='renewOff'?'关闭自动续费':'删除'}？`,'批量操作');}catch{return;}try{for(const row of selected.value){if(action==='restore')await post(`/devices/${row.id}/restore`);else if(action.startsWith('renew'))await patch(`/devices/${row.id}/auto-renew`,{enabled:action==='renewOn'});else await remove(`/devices/${row.id}?permanent=${recycled.value}`);}ElMessage.success('操作完成');}finally{await load();}}
function renew(row:any){router.push({path:'/agentIp/renew3',query:{deviceId:row.id}});}
const expired=(row:any)=>row.expiresAt&&new Date(row.expiresAt).getTime()<Date.now();
const date=(value:string)=>value?new Date(value).toLocaleString():'—';
</script>
<template><section class="panel page-list"><h1 class="page-title">{{recycled?'设备回收站':'设备列表'}}</h1>
  <el-alert v-if="!recycled&&stats.willExpiredIp" :title="`即将到期设备 ${stats.willExpiredIp} 个，请及时续费。`" type="warning" :closable="false"/>
  <div class="stat-grid"><button v-for="[key,label] in categories" :key="key" :class="{active:category===key}" @click="category=key!">{{label}}<b>{{stats[key!]||0}}</b></button></div>
  <div class="toolbar"><template v-if="!recycled"><el-button v-if="permissions.can('device.buy')" type="primary" @click="router.push({path:'/agentIp/aggregateBuy3',query:{type}})">购买设备服务</el-button><el-button v-if="permissions.can('device.renew')" :disabled="selected.length!==1" @click="renew(selected[0])">续费设备</el-button></template><el-button v-if="permissions.can('device.export')" @click="exportAll">导出设备</el-button><el-input v-model="query" class="search" placeholder="设备名称 / 地址 / 地域 / 备注" clearable @clear="page=1;load()" @keyup.enter="page=1;load()"/><el-button :icon="Search" @click="page=1;load()">查询</el-button><el-button :icon="Refresh" aria-label="刷新设备" @click="load"/></div>
  <el-tabs v-model="type" @tab-change="category='allIp'"><el-tab-pane v-for="[id,label] in [[1,'平台设备'],[20,'专享平台设备']]" :key="String(id)" :label="`${label} (${counts[Number(id)]||0})`" :name="Number(id)"/></el-tabs>
  <el-table :data="items" v-loading="loading" row-key="id" @selection-change="selected=$event"><el-table-column type="selection" width="42"/><el-table-column label="设备名称" min-width="160"><template #default="{row}"><button class="table-link" @click="edit(row)" :disabled="!permissions.can('device.edit')">{{row.name}}</button><div class="table-sub">{{row.id.slice(0,8)}}</div></template></el-table-column><el-table-column label="设备信息" min-width="175"><template #default="{row}">{{row.host}}:{{row.port}}<div class="table-sub">{{row.protocol.toUpperCase()}} {{row.packageId?' · '+row.packageId:''}}</div></template></el-table-column><el-table-column prop="region" label="设备地域" min-width="110"/><el-table-column label="绑定店铺" width="100"><template #default="{row}"><button v-if="permissions.can('shop.view')" class="table-link" @click="showBindings(row)">{{row.boundCount||0}} 个店铺</button><span v-else>{{row.boundCount||0}}</span></template></el-table-column><el-table-column prop="remark" label="备注" min-width="110" show-overflow-tooltip/><el-table-column label="计费模式" width="100"><template #default>按期限</template></el-table-column><el-table-column label="设备状态" width="110"><template #default="{row}"><el-tag :type="recycled?'info':expired(row)?'danger':'success'">{{recycled?'已回收':expired(row)?'已到期':'有效'}}</el-tag></template></el-table-column><el-table-column label="到期时间" min-width="175"><template #default="{row}">{{date(row.expiresAt)}}<div v-if="!recycled" class="table-sub">自动续费 <el-switch :model-value="Boolean(row.autoRenew)" size="small" :disabled="!permissions.can('device.renew')" @change="autoRenew(row)"/></div></template></el-table-column><el-table-column label="操作" width="175" fixed="right"><template #default="{row}"><template v-if="!recycled"><el-button v-if="permissions.can('device.renew')" link type="primary" @click="renew(row)">续费</el-button><el-button v-if="permissions.can('device.edit')" link type="primary" @click="edit(row)">编辑</el-button><el-dropdown trigger="click"><el-button link>更多<el-icon><ArrowDown/></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-if="permissions.can('device.edit')" @click="check(row)">检测代理</el-dropdown-item><el-dropdown-item v-if="permissions.can('shop.view')" @click="showBindings(row)">绑定店铺</el-dropdown-item><el-dropdown-item v-if="permissions.can('device.edit')" divided @click="recycle(row)">删除设备</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template><template v-else><el-button v-if="permissions.can('device.edit')" link type="primary" @click="restore(row)">恢复</el-button><el-button v-if="permissions.can('device.edit')" link type="danger" @click="recycle(row)">永久删除</el-button></template></template></el-table-column><template #empty><el-empty :description="recycled?'回收站暂无设备':'暂无设备数据'" :image-size="90"/></template></el-table>
  <div class="table-pagination"><div class="batch-actions"><span class="muted">已选 {{selected.length}} 个</span><el-button v-if="permissions.can('device.edit')" size="small" :disabled="!selected.length" @click="batch('delete')">{{recycled?'永久删除':'批量删除'}}</el-button><el-button v-if="recycled&&permissions.can('device.edit')" size="small" :disabled="!selected.length" @click="batch('restore')">批量恢复</el-button><el-dropdown v-if="!recycled&&permissions.can('device.renew')" @command="batch"><el-button size="small" :disabled="!selected.length">自动续费<el-icon><ArrowDown/></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="renewOn">开启自动续费</el-dropdown-item><el-dropdown-item command="renewOff">关闭自动续费</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div><el-pagination v-model:current-page="page" v-model:page-size="size" :page-sizes="[20,50,100]" :total="total" layout="total,sizes,prev,pager,next,jumper" @current-change="load" @size-change="page=1;load()"/></div>
</section>
<el-drawer :model-value="Boolean(bindings)" title="绑定店铺" size="640px" @close="bindings=undefined"><template v-if="bindings"><h3>{{bindings.name}}</h3><p class="muted">{{bindings.host}} · {{bindings.region}}</p><el-table :data="boundShops"><el-table-column prop="name" label="店铺名称"/><el-table-column prop="platform" label="平台"/><el-table-column label="操作" width="100"><template #default="{row}"><el-button v-if="permissions.can('shop.edit')" link type="danger" @click="unbindShop(row)">解绑</el-button></template></el-table-column></el-table><template v-if="permissions.can('shop.edit')"><h3 class="section-title">绑定已有店铺</h3><div class="toolbar"><el-input v-model="shopSearch" placeholder="搜索店铺名称" @keyup.enter="searchShops"/><el-button @click="searchShops">搜索</el-button></div><el-select v-model="shopId" placeholder="选择店铺"><el-option v-for="shop in shopChoices" :key="shop.id" :value="shop.id" :label="`${shop.name}${shop.deviceId?'（将替换原绑定）':''}`"/></el-select><el-button type="primary" style="margin-top:16px" :disabled="!shopId" @click="bindShop">确认绑定</el-button></template></template></el-drawer>
<el-dialog v-model="editing" title="编辑设备" width="520px" :close-on-click-modal="false"><el-form label-position="top"><el-form-item label="设备名称" required><el-input v-model="form.name" maxlength="120"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" maxlength="500" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="editing=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!form.name?.trim()" @click="save">保存</el-button></template></el-dialog></template>
